def canonical(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def digest(path: Path) -> str:
    return hashlib.sha256(
        canonical(path.read_text(encoding="utf-8")).encode("utf-8")
    ).hexdigest()


def main() -> int:
    root = Path.cwd()

    for rel, expected in EXPECTED.items():
        path = root / rel
        if not path.is_file():
            print(f"ABORTED: expected file missing: {rel}")
            print("No files were changed.")
            return 2
        actual = digest(path)
        if actual != expected:
            print(f"ABORTED: local file differs from the reviewed backend-AI version: {rel}")
            print(f"Expected SHA-256: {expected}")
            print(f"Actual SHA-256:   {actual}")
            print("No files were changed.")
            return 3

    new_test = root / "tests/test_ai_false_multi_person_guard.py"
    if new_test.exists():
        print("ABORTED: tests/test_ai_false_multi_person_guard.py already exists.")
        print("No files were changed.")
        return 4

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / f".ai-false-multi-person-guard-backup-{stamp}"

    for rel in EXPECTED:
        source = root / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)

    for rel, content in CONTENTS.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")

    print("AI FALSE MULTI-PERSON GUARD APPLIED")
    print(f"Backup: {backup}")
    print("")
    print("Fixed:")
    print("- AI must prove each returned name is explicitly reported missing")
    print("- page/post authors, contacts, relatives and nearby names are excluded")
    print("- every accepted AI person carries a direct missing-status evidence excerpt")
    print("- a deterministic backend gate rejects unsupported AI-proposed people")
    print("- Facebook public-post text no longer selects unrelated long JSON-LD content")
    print("- genuine multi-person missing lists still remain supported")
    print("- no database migration required")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
